import{_ as i,o as t,c as l,aw as s}from"./chunks/framework.DLufY-ao.js";const h=JSON.parse('{"title":"Типизация","description":"","frontmatter":{},"headers":[],"relativePath":"js/js/typing/typing.md","filePath":"wiki/dev-commit/js/js/typing/typing.md"}'),o={name:"js/js/typing/typing.md"};function r(e,a,n,c,p,u){return t(),l("div",null,[...a[0]||(a[0]=[s('<h1 id="типизация" tabindex="-1">Типизация <a class="header-anchor" href="#типизация" aria-label="Permalink to &quot;Типизация&quot;">​</a></h1><h2 id="языки-программирования" tabindex="-1">Языки программирования <a class="header-anchor" href="#языки-программирования" aria-label="Permalink to &quot;Языки программирования&quot;">​</a></h2><ol><li>Типизированные</li><li>Нетипизированные (бестиповые) [Ассемблер, Forth и Brainfuck]</li></ol><h2 id="виды-типизации" tabindex="-1">Виды типизации <a class="header-anchor" href="#виды-типизации" aria-label="Permalink to &quot;Виды типизации&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">TIP</p><ul><li><strong>Статическая типизация</strong> - тип задается при определении переменной, нельзя положить переменную другого типа. Конечные типы переменных и функций устанавливаются на этапе компиляции (компилятор точно знает, какой тип где находится) [C, Java, C#]</li><li><strong>Динамическая типизация</strong> - тип не задается. Все типы выясняются уже во время выполнения программы. Возможна запись в переменную значения другого типа [Python, JavaScript, Ruby]</li></ul></div><div class="tip custom-block"><p class="custom-block-title">TIP</p><ul><li><strong>Сильная типизация (строгая)</strong> - язык не позволяет смешивать в выражениях различные типы и не выполняет автоматические неявные преобразования, например нельзя вычесть из строки множество [Java, Python, Haskell, Lisp]</li><li><strong>Слабая типизация (нестрогая)</strong> - неявное приведение типов. Н-р: операции сложения с разными типами данных. Автоматически выполняется множество неявных преобразований, даже если может произойти потеря точности или преобразование неоднозначно [C, JavaScript, Visual Basic, PHP]</li></ul></div><div class="tip custom-block"><p class="custom-block-title">TIP</p><ul><li><strong>Явная типизация</strong> - тип новых переменных / функций / их аргументов нужно задавать явно [C++, D, C#]</li><li><strong>Неявная типизация</strong> - перекладывают эту задачу на компилятор / интерпретатор [PHP, Lua, JavaScript]</li></ul></div><h2 id="примеры-типизации" tabindex="-1">Примеры типизации <a class="header-anchor" href="#примеры-типизации" aria-label="Permalink to &quot;Примеры типизации&quot;">​</a></h2><ol><li>Статическая [C, Java,C#]</li><li>Динамическая [JavaScript, PHP, Python, Ruby]</li><li>Строгая (сильная) [Java, Python, Haskell, Lisp]</li><li>Нестрогая (слабая) [PHP, JavaScript, Visual Basic]</li><li>Явная [C++, D, C#]</li><li>Неявная [JavaScript, PHP, Lua]</li></ol>',9)])])}const P=i(o,[["render",r]]);export{h as __pageData,P as default};
